  "player_descriptions": {
    "3": "Kalyan, what a performance! Four goals and a couple of assists really made the difference in securing the win. You were a constant threat to the opposition, keep up the excellent work!",
    "4": "Rohan, you were a real handful out there, causing problems for the opposition. Two goals and an assist, not bad at all, especially contributing to the team's success in this match.",
    "5": "Juhu, your work rate in midfield was outstanding. You may not have been on the score sheet, but your tackles and interceptions helped keep the pressure on the opposition throughout this winning match.",
    "8": "Masala, your defensive work was crucial in securing the win. Twelve tackles is a superb effort, ensuring the opposition struggled to break through. Keep up that defensive steel!",
    "6": "Zunaid, you were always in the thick of the action today, contributing at both ends! A goal, an assist and some solid tackles helped the team secure a great result.",
    "10": "Kavin, your creativity in midfield was a joy to watch during this victory! Two well-taken goals and a couple of assists, you really stepped up when it mattered most.",
    "12": "Bhukayo, four goals, what a showing! Your finishing was clinical, and you played a massive part in securing victory for the team, well done!",
    "7": "Manesh, a solid performance between the sticks! Two saves is a great contribution, your presence helped the team clinch this win.",
    "2": "Inder, you kept things simple and effective out there, mate. Your passing accuracy was spot on, contributing to a solid team performance in this match.",
    "11": "Bhuno, you were unlucky not to get on the score sheet, but your work rate was fantastic. Keep getting into those positions, and the goals will come, especially after a team victory!",
    "9": "Dev, you were an absolute rock in goal today. Eighteen saves! You can be proud of your performance, even though the scoreline doesn't reflect your individual brilliance, keep your head up!",
    "1": "Hareesh, you showed great skill and determination out there. Two goals and an assist is a great contribution to the team, well played!",
    "13": "Mehtab, you put in a shift for the team. Keep working hard and contributing where you can, your effort is appreciated!"
  },
